/**
 * Late enforcement. Generated by tools/generate_overlays.py from
 * tools/late_results/actions.json; do not edit.
 *
 * <p>account.risk_changed only wakes the handler. {@link #handleRiskChange} verifies the delivery,
 * reads the account's current risk (GET /v1/accounts/{account_id}), asks your getAccountState where
 * the account is in your own flow, and takes the actions the table names for that state and the
 * decision of its flow:
 *
 * <pre>
 *   onboarding   account_creation review/block  fail_onboarding, revoke_sessions
 *   provisional  account_creation review/block  reject_activation, revoke_sessions
 *   active       login review                   revoke_sessions
 *   active       login block                    restrict, revoke_sessions
 *   restricted   login allow                    unrestrict, when the login FlowPolicy reinstates
 * </pre>
 *
 * <p>Every action, or none, is recorded with accounts().recordEnforcement at the riskVersion read,
 * and a refused action is recorded as failed and thrown. No action deletes a user. The same table
 * and vectors (tests/fixtures/late-results-vectors.json) run in every SDK.
 */
public final class LateResults {
    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final JsonNode TABLE = parse("{\"lifecycle\":{\"onboarding\":{\"flow\":\"account_creation\",\"on\":{\"review\":[\"fail_onboarding\",\"revoke_sessions\"],\"block\":[\"fail_onboarding\",\"revoke_sessions\"]}},\"provisional\":{\"flow\":\"account_creation\",\"on\":{\"review\":[\"reject_activation\",\"revoke_sessions\"],\"block\":[\"reject_activation\",\"revoke_sessions\"]}},\"active\":{\"flow\":\"login\",\"on\":{\"review\":[\"revoke_sessions\"],\"block\":[\"restrict\",\"revoke_sessions\"]}},\"restricted\":{\"flow\":\"login\",\"on\":{},\"reinstate\":{\"allow\":[\"unrestrict\"]}},\"rejected\":{\"flow\":\"account_creation\",\"on\":{}}},\"providers\":{\"clerk\":{\"base_url\":\"https://api.clerk.com/v1\",\"actions\":{\"fail_onboarding\":[{\"call\":{\"method\":\"POST\",\"path\":\"/users/{user}/ban\"}}],\"reject_activation\":[{\"call\":{\"method\":\"POST\",\"path\":\"/users/{user}/ban\"}}],\"restrict\":[{\"call\":{\"method\":\"POST\",\"path\":\"/users/{user}/ban\"}}],\"unrestrict\":[{\"call\":{\"method\":\"POST\",\"path\":\"/users/{user}/unban\"}}],\"revoke_sessions\":[{\"each\":{\"list\":{\"method\":\"GET\",\"path\":\"/sessions\",\"query\":{\"user_id\":\"{user}\",\"status\":\"active\",\"limit\":\"100\"}},\"page\":{\"kind\":\"offset\",\"param\":\"offset\",\"size\":100},\"where\":{\"status\":\"active\"}},\"call\":{\"method\":\"POST\",\"path\":\"/sessions/{item}/revoke\"}}]}},\"workos\":{\"base_url\":\"https://api.workos.com\",\"actions\":{\"fail_onboarding\":[{\"call\":{\"method\":\"PUT\",\"path\":\"/user_management/users/{user}\",\"body\":{\"metadata\":{\"noresponse_state\":\"onboarding_failed\"}}}}],\"reject_activation\":[{\"call\":{\"method\":\"PUT\",\"path\":\"/user_management/users/{user}\",\"body\":{\"metadata\":{\"noresponse_state\":\"activation_rejected\"}}}}],\"restrict\":[{\"call\":{\"method\":\"PUT\",\"path\":\"/user_management/users/{user}\",\"body\":{\"metadata\":{\"noresponse_state\":\"restricted\"}}}}],\"unrestrict\":[{\"call\":{\"method\":\"PUT\",\"path\":\"/user_management/users/{user}\",\"body\":{\"metadata\":{\"noresponse_state\":null}}}}],\"revoke_sessions\":[{\"each\":{\"list\":{\"method\":\"GET\",\"path\":\"/user_management/users/{user}/sessions\",\"query\":{\"limit\":\"100\"}},\"page\":{\"kind\":\"cursor\",\"param\":\"after\",\"next\":[\"list_metadata\",\"after\"]},\"where\":{\"status\":\"active\"}},\"call\":{\"method\":\"POST\",\"path\":\"/user_management/sessions/revoke\",\"body\":{\"session_id\":\"{item}\"}}}]}},\"auth0\":{\"base_url\":\"https://{domain}/api/v2\",\"actions\":{\"fail_onboarding\":[{\"call\":{\"method\":\"PATCH\",\"path\":\"/users/{user}\",\"body\":{\"blocked\":true}}}],\"reject_activation\":[{\"call\":{\"method\":\"PATCH\",\"path\":\"/users/{user}\",\"body\":{\"blocked\":true}}}],\"restrict\":[{\"call\":{\"method\":\"PATCH\",\"path\":\"/users/{user}\",\"body\":{\"blocked\":true}}}],\"unrestrict\":[{\"call\":{\"method\":\"PATCH\",\"path\":\"/users/{user}\",\"body\":{\"blocked\":false}}}],\"revoke_sessions\":[{\"call\":{\"method\":\"DELETE\",\"path\":\"/users/{user}/sessions\"},\"fallback\":{\"status\":403,\"code\":\"feature_not_enabled\",\"reports\":\"restrict\",\"steps\":[{\"call\":{\"method\":\"PATCH\",\"path\":\"/users/{user}\",\"body\":{\"blocked\":true}}}]}},{\"call\":{\"method\":\"DELETE\",\"path\":\"/users/{user}/refresh-tokens\"},\"fallback\":{\"status\":403,\"code\":\"feature_not_enabled\",\"steps\":[{\"each\":{\"list\":{\"method\":\"GET\",\"path\":\"/device-credentials\",\"query\":{\"user_id\":\"{user}\",\"type\":\"refresh_token\",\"per_page\":\"100\"}},\"page\":{\"kind\":\"index\",\"param\":\"page\",\"size\":100}},\"call\":{\"method\":\"DELETE\",\"path\":\"/device-credentials/{item}\"}},{\"each\":{\"list\":{\"method\":\"GET\",\"path\":\"/device-credentials\",\"query\":{\"user_id\":\"{user}\",\"type\":\"rotating_refresh_token\",\"per_page\":\"100\"}},\"page\":{\"kind\":\"index\",\"param\":\"page\",\"size\":100}},\"call\":{\"method\":\"DELETE\",\"path\":\"/device-credentials/{item}\"}}]}}]}}},\"limits\":{\"retries\":4,\"budget_ms\":3000,\"backoff_ms\":250,\"max_pages\":100}}");
    private static final JsonNode LIMITS = TABLE.get("limits");
    private static final Pattern SLUG = Pattern.compile("^[a-z0-9_.-]+$");

    private LateResults() {}

    private static JsonNode parse(String json) {
        try {
            return MAPPER.readTree(json);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Where the account is in your flow, from getAccountState. */
    public static final class AccountStateAnswer {
        private final String state;
        private final String userId;
        private final Long enforcedRiskVersion;

        /**
         * @param state onboarding, provisional, active, restricted or rejected
         * @param userId the provider's user id; null for the account id, as when you assess with the provider's user id
         * @param enforcedRiskVersion the riskVersion you last enforced (a result's riskVersion that you stored), or null;
         *     an account at or below it is skipped
         */
        public AccountStateAnswer(String state, String userId, Long enforcedRiskVersion) {
            this.state = Objects.requireNonNull(state, "state");
            this.userId = userId;
            this.enforcedRiskVersion = enforcedRiskVersion;
        }

        public static AccountStateAnswer of(String state) {
            return new AccountStateAnswer(state, null, null);
        }

        public String state() {
            return state;
        }

        public Optional<String> userId() {
            return Optional.ofNullable(userId);
        }

        public Optional<Long> enforcedRiskVersion() {
            return Optional.ofNullable(enforcedRiskVersion);
        }
    }

    /** Per-flow policy. */
    public static final class FlowPolicy {
        private final boolean reinstate;

        /** @param reinstate lift a restriction once the flow's decision is allow again; off by default */
        public FlowPolicy(boolean reinstate) {
            this.reinstate = reinstate;
        }

        public boolean reinstate() {
            return reinstate;
        }
    }

    /** One recorded enforcement. */
    public static final class Enforced {
        private final String flow;
        private final String action;
        private final String status;
        private final String errorCode;

        Enforced(String flow, String action, String status, String errorCode) {
            this.flow = flow;
            this.action = action;
            this.status = status;
            this.errorCode = errorCode;
        }

        public String flow() {
            return flow;
        }

        public String action() {
            return action;
        }

        /** applied or failed. */
        public String status() {
            return status;
        }

        public Optional<String> errorCode() {
            return Optional.ofNullable(errorCode);
        }
    }

    /**
     * What was done. skipped says why nothing was: not_actionable (not account.risk_changed, or a test
     * event), account_gone (erased), unknown_user (getAccountState returned null) or already_enforced.
     */
    public static final class EnforcementResult {
        private final WebhookEvent event;
        private final Account account;
        private final String state;
        private final Long riskVersion;
        private final String skipped;
        private final List<Enforced> enforcements;

        EnforcementResult(WebhookEvent event, Account account, String state, Long riskVersion, String skipped,
                List<Enforced> enforcements) {
            this.event = event;
            this.account = account;
            this.state = state;
            this.riskVersion = riskVersion;
            this.skipped = skipped;
            this.enforcements = Collections.unmodifiableList(enforcements);
        }

        EnforcementResult withEvent(WebhookEvent event) {
            return new EnforcementResult(event, account, state, riskVersion, skipped, enforcements);
        }

        /** The verified event, from handleRiskChange. Answer an endpoint.verification with its challenge. */
        public Optional<WebhookEvent> event() {
            return Optional.ofNullable(event);
        }

        public Optional<Account> account() {
            return Optional.ofNullable(account);
        }

        public Optional<String> state() {
            return Optional.ofNullable(state);
        }

        /** The riskVersion acted on. Store it and return it as enforcedRiskVersion. */
        public Optional<Long> riskVersion() {
            return Optional.ofNullable(riskVersion);
        }

        public Optional<String> skipped() {
            return Optional.ofNullable(skipped);
        }

        /** What was recorded, in order. */
        public List<Enforced> enforcements() {
            return enforcements;
        }
    }

    /** The provider refused an action or could not be reached (status 0). Answer the webhook with a 5xx so it is delivered again. */
    public static final class ProviderActionException extends RuntimeException {
        private static final long serialVersionUID = 1L;

        private final String provider;
        private final int status;
        private final String code;

        public ProviderActionException(String provider, int status, String message, String code) {
            super(message);
            this.provider = provider;
            this.status = status;
            this.code = code;
        }

        public String provider() {
            return provider;
        }

        public int status() {
            return status;
        }

        /** The provider's error code, such as Auth0's errorCode "insufficient_scope", when it sent one. */
        public Optional<String> code() {
            return Optional.ofNullable(code);
        }
    }

    /** Runs one action in an identity provider. Build one with identityProvider or customProvider. */
    public interface ActionProvider {
        /** clerk, workos, auth0 or custom. */
        String name();

        /**
         * Take the action (revoke_sessions, restrict, unrestrict, fail_onboarding or reject_activation) and
         * return any other action that had to run with it (Auth0 restricts to end a session).
         */
        List<String> run(String action, String userId);
    }

    /** One action of your own user store. Return other actions that ran with it, or null. */
    public interface ActionHandler {
        List<String> run(String userId);
    }

    /** What handleRiskChange and enforceAccount need. */
    public static final class EnforcementOptions {
        private final ActionProvider provider;
        private final Function<Account, AccountStateAnswer> getAccountState;
        private final Map<String, FlowPolicy> flows = new HashMap<>();
        private Duration tolerance = Duration.ofSeconds(Webhook.DEFAULT_TOLERANCE_SECONDS);
        private Instant now;

        /**
         * @param getAccountState the account's state in your flow; null for an account you do not hold
         */
        public EnforcementOptions(ActionProvider provider, Function<Account, AccountStateAnswer> getAccountState) {
            this.provider = Objects.requireNonNull(provider, "provider");
            this.getAccountState = Objects.requireNonNull(getAccountState, "getAccountState");
        }

        /** Set the policy of one flow: account_creation, login or purchase. */
        public EnforcementOptions flow(String flow, FlowPolicy policy) {
            flows.put(flow, policy);
            return this;
        }

        /** The webhook timestamp tolerance. Default Webhook.DEFAULT_TOLERANCE_SECONDS. */
        public EnforcementOptions tolerance(Duration tolerance) {
            this.tolerance = tolerance;
            return this;
        }

        /** The clock the timestamp is checked against. Default now. */
        public EnforcementOptions now(Instant now) {
            this.now = now;
            return this;
        }
    }

    /**
     * Verify an account.risk_changed delivery and enforce the account's current risk. A delivery that
     * fails verification throws WebhookVerificationException before anything is read; any other event,
     * and a test event, does nothing.
     */
    public static EnforcementResult handleRiskChange(NoResponse client, byte[] payload,
            Map<String, ? extends Collection<String>> headers, Map<String, String> secrets, EnforcementOptions options) {
        WebhookEvent event = Webhook.constructEvent(payload, headers, secrets, options.tolerance,
                options.now != null ? options.now : Instant.now());
        if (!(event instanceof AccountRiskChangedEvent)
                || ((AccountRiskChangedEvent) event).test().orElse(false)) {
            return new EnforcementResult(event, null, null, null, "not_actionable", List.of());
        }
        String accountId = ((AccountRiskChangedEvent) event).data().account().id();
        Account account;
        try {
            account = client.accounts().get(accountId).account().orElseThrow();
        } catch (NotFoundException e) {
            return new EnforcementResult(event, null, null, null, "account_gone", List.of());
        }
        return enforceAccount(client, account, options).withEvent(event);
    }

    /**
     * Enforce one account as read: the account a handler fetched, or one from
     * accounts().listChanged() with unenforced true when catching up.
     */
    public static EnforcementResult enforceAccount(NoResponse client, Account account, EnforcementOptions options) {
        AccountStateAnswer answer = options.getAccountState.apply(account);
        if (answer == null) {
            return new EnforcementResult(null, account, null, null, "unknown_user", List.of());
        }
        String state = answer.state();
        JsonNode rule = TABLE.get("lifecycle").get(state);
        if (rule == null) {
            throw new IllegalArgumentException("unknown account state " + state);
        }
        long riskVersion = account.riskVersion();
        if (answer.enforcedRiskVersion != null && riskVersion <= answer.enforcedRiskVersion) {
            return new EnforcementResult(null, account, state, riskVersion, "already_enforced", List.of());
        }
        String flow = rule.get("flow").asText();
        String decision = decision(account, flow);
        FlowPolicy policy = options.flows.get(flow);
        List<String> actions = strings(rule.get("on").get(decision));
        if (actions == null && policy != null && policy.reinstate() && rule.has("reinstate")) {
            actions = strings(rule.get("reinstate").get(decision));
        }
        ActionProvider provider = options.provider;
        List<Enforced> enforcements = new ArrayList<>();
        Recorder record = (action, status, errorCode) -> {
            client.accounts().recordEnforcement(account.id(), EnforcementRequest.builder()
                    .riskVersion(riskVersion)
                    .flow(Flow.of(flow))
                    .action(EnforcementAction.of(action))
                    .stateBefore(EnforcementState.of(state))
                    .status(EnforcementStatus.of(status))
                    .provider(EnforcementProvider.of(provider.name()))
                    .errorCode(errorCode)
                    .build());
            enforcements.add(new Enforced(flow, action, status, errorCode));
        };
        if (actions == null || actions.isEmpty()) {
            // An adverse or step_up decision that needs nothing still counts as handled.
            if (!"allow".equals(decision)) {
                record.record("none", "applied", null);
            }
            return new EnforcementResult(null, account, state, riskVersion, null, enforcements);
        }
        String userId = answer.userId().filter(id -> !id.isEmpty()).orElse(account.id());
        Set<String> recorded = new LinkedHashSet<>();
        for (String action : actions) {
            List<String> alsoRan;
            try {
                alsoRan = provider.run(action, userId);
            } catch (RuntimeException e) {
                record.record(action, "failed", failureCode(provider.name(), e));
                throw e;
            }
            List<String> ran = new ArrayList<>(alsoRan == null ? List.of() : alsoRan);
            ran.add(action);
            for (String done : ran) {
                if (recorded.add(done)) {
                    record.record(done, "applied", null);
                }
            }
        }
        return new EnforcementResult(null, account, state, riskVersion, null, enforcements);
    }

    private interface Recorder {
        void record(String action, String status, String errorCode);
    }

    private static String decision(Account account, String flow) {
        AccountDecision decision;
        switch (flow) {
            case "account_creation":
                decision = account.decisionsByFlow().accountCreation();
                break;
            case "login":
                decision = account.decisionsByFlow().login();
                break;
            default:
                decision = account.decisionsByFlow().purchase();
        }
        return decision.value();
    }

    private static List<String> strings(JsonNode array) {
        if (array == null || !array.isArray()) {
            return null;
        }
        List<String> out = new ArrayList<>();
        array.forEach(node -> out.add(node.asText()));
        return out;
    }

    /** The error_code of a failed action: the provider's code, else its HTTP status, as provider.code. */
    private static String failureCode(String provider, RuntimeException error) {
        String code = null;
        Integer status = null;
        if (error instanceof ProviderActionException) {
            ProviderActionException refused = (ProviderActionException) error;
            code = refused.code;
            status = refused.status;
        }
        String suffix;
        if (code != null && SLUG.matcher(code.toLowerCase(java.util.Locale.ROOT)).matches()) {
            suffix = code.toLowerCase(java.util.Locale.ROOT);
        } else if (status != null && status == 0) {
            suffix = "unreachable";
        } else if (status != null) {
            suffix = "http_" + status;
        } else {
            suffix = "error";
        }
        String full = provider + "." + suffix;
        return full.length() > 128 ? full.substring(0, 128) : full;
    }

    /** Options for {@link #identityProvider}. */
    public static final class IdentityProviderOptions {
        private final String token;
        private String domain;
        private String baseUrl;
        private HTTPClient http;

        /** @param token the Clerk secret key, WorkOS API key or Auth0 Management API token */
        public IdentityProviderOptions(String token) {
            this.token = token;
        }

        /** The Auth0 tenant domain, such as example.eu.auth0.com. */
        public IdentityProviderOptions domain(String domain) {
            this.domain = domain;
            return this;
        }

        /** The admin API's base URL, in place of the table's (or of domain). */
        public IdentityProviderOptions baseUrl(String baseUrl) {
            this.baseUrl = baseUrl;
            return this;
        }

        /** The HTTP client, for a proxy or for tests. Default the JDK client. */
        public IdentityProviderOptions http(HTTPClient http) {
            this.http = http;
            return this;
        }
    }

    /** Clerk, WorkOS or Auth0 (clerk, workos, auth0), run from the shared action table. */
    public static ActionProvider identityProvider(String name, IdentityProviderOptions options) {
        JsonNode spec = TABLE.get("providers").get(name);
        if (spec == null) {
            throw new IllegalArgumentException("unknown identity provider " + name);
        }
        if (options == null || options.token == null || options.token.isEmpty()) {
            throw new IllegalArgumentException(name + " needs token");
        }
        String base = options.baseUrl != null ? options.baseUrl : spec.get("base_url").asText();
        if (base.contains("{domain}")) {
            if (options.domain == null || options.domain.isEmpty()) {
                throw new IllegalArgumentException(name + " needs domain or baseUrl");
            }
            base = base.replace("{domain}", options.domain);
        }
        String root = base.replaceAll("/+$", "");
        String authorization = "Bearer " + options.token;
        HTTPClient http = options.http != null ? options.http : new HTTPClient() {};
        return new ActionProvider() {
            @Override
            public String name() {
                return name;
            }

            @Override
            public List<String> run(String action, String userId) {
                if (userId == null || userId.isEmpty()) {
                    throw new IllegalArgumentException("user id must be a non-empty string");
                }
                JsonNode steps = spec.get("actions").get(action);
                if (steps == null) {
                    throw new IllegalArgumentException("unknown action " + action);
                }
                return runSteps(steps, new Context(name, root, authorization, http, userId));
            }
        };
    }

    /** Your own user store: one handler per action you support, keyed by action. An action without one fails. */
    public static ActionProvider customProvider(Map<String, ActionHandler> handlers) {
        Map<String, ActionHandler> copy = Map.copyOf(handlers);
        return new ActionProvider() {
            @Override
            public String name() {
                return "custom";
            }

            @Override
            public List<String> run(String action, String userId) {
                ActionHandler handler = copy.get(action);
                if (handler == null) {
                    throw new IllegalArgumentException("customProvider has no " + action + " handler");
                }
                List<String> alsoRan = handler.run(userId);
                return alsoRan == null ? List.of() : alsoRan;
            }
        };
    }

    private static final class Context {
        final String name;
        final String base;
        final String authorization;
        final HTTPClient http;
        final String user;
        long waitedMs;

        Context(String name, String base, String authorization, HTTPClient http, String user) {
            this.name = name;
            this.base = base;
            this.authorization = authorization;
            this.http = http;
            this.user = user;
        }
    }

    private static List<String> runSteps(JsonNode steps, Context ctx) {
        List<String> alsoRan = new ArrayList<>();
        for (JsonNode step : steps) {
            if (step.has("each")) {
                for (String item : collect(step.get("each"), ctx)) {
                    send(step.get("call"), null, ctx, item);
                }
                continue;
            }
            try {
                send(step.get("call"), null, ctx, null);
            } catch (ProviderActionException e) {
                JsonNode fallback = step.get("fallback");
                if (fallback == null
                        || e.status != fallback.get("status").asInt()
                        || !fallback.get("code").asText().equals(e.code)) {
                    throw e;
                }
                alsoRan.addAll(runSteps(fallback.get("steps"), ctx));
                if (fallback.has("reports")) {
                    alsoRan.add(fallback.get("reports").asText());
                }
            }
        }
        return alsoRan;
    }

    /** Every matching item id across the list's pages, collected before any is acted on. */
    private static List<String> collect(JsonNode each, Context ctx) {
        JsonNode list = each.get("list");
        JsonNode page = each.get("page");
        JsonNode where = each.get("where");
        String kind = page.get("kind").asText();
        String param = page.get("param").asText();
        int size = page.path("size").asInt(0);
        List<String> ids = new ArrayList<>();
        String cursor = null;
        for (int index = 0; index < LIMITS.get("max_pages").asInt(); index++) {
            Map<String, String> query = new LinkedHashMap<>();
            if ("offset".equals(kind)) {
                query.put(param, String.valueOf(index * size));
            } else if ("index".equals(kind)) {
                query.put(param, String.valueOf(index));
            } else if (cursor != null) {
                query.put(param, cursor);
            }
            JsonNode body = send(list, query, ctx, null);
            JsonNode items = body != null && body.isArray() ? body : body != null ? body.path("data") : null;
            int count = 0;
            if (items != null && items.isArray()) {
                for (JsonNode item : items) {
                    count++;
                    JsonNode id = item.get("id");
                    if (id == null || !id.isTextual() || id.asText().isEmpty() || !matches(item, where)) {
                        continue;
                    }
                    ids.add(id.asText());
                }
            }
            if ("cursor".equals(kind)) {
                JsonNode next = body;
                for (JsonNode key : page.get("next")) {
                    next = next == null ? null : next.get(key.asText());
                }
                if (next == null || !next.isTextual() || next.asText().isEmpty()) {
                    break;
                }
                cursor = next.asText();
            } else if (count < size) {
                break;
            }
        }
        return ids;
    }

    private static boolean matches(JsonNode item, JsonNode where) {
        if (where == null) {
            return true;
        }
        for (Iterator<Map.Entry<String, JsonNode>> it = where.fields(); it.hasNext(); ) {
            Map.Entry<String, JsonNode> entry = it.next();
            if (!entry.getValue().equals(item.get(entry.getKey()))) {
                return false;
            }
        }
        return true;
    }

    private static String fill(String value, String user, String item) {
        return value.replace("{user}", user).replace("{item}", item == null ? "" : item);
    }

    private static JsonNode fillJson(JsonNode value, String user, String item) {
        if (value.isTextual()) {
            return MAPPER.getNodeFactory().textNode(fill(value.asText(), user, item));
        }
        if (value.isArray()) {
            ArrayNode out = MAPPER.createArrayNode();
            value.forEach(entry -> out.add(fillJson(entry, user, item)));
            return out;
        }
        if (value.isObject()) {
            ObjectNode out = MAPPER.createObjectNode();
            value.fields().forEachRemaining(entry -> out.set(entry.getKey(), fillJson(entry.getValue(), user, item)));
            return out;
        }
        return value;
    }

    private static String encode(String value) {
        return URLEncoder.encode(value, StandardCharsets.UTF_8).replace("+", "%20");
    }

    /** How long a 429 asks to wait, in milliseconds. */
    private static long rateLimitWaitMs(HttpResponse<?> response, int retry) {
        Optional<Double> after = number(response.headers().firstValue("retry-after"));
        if (after.isPresent() && after.get() >= 0) {
            return (long) (after.get() * 1000);
        }
        Optional<Double> reset = number(response.headers().firstValue("x-ratelimit-reset"));
        if (reset.isPresent()) {
            return Math.max(0L, (long) (reset.get() * 1000) - System.currentTimeMillis());
        }
        return LIMITS.get("backoff_ms").asLong() << retry;
    }

    private static Optional<Double> number(Optional<String> text) {
        try {
            return text.map(String::trim).filter(t -> !t.isEmpty()).map(Double::parseDouble)
                    .filter(d -> !d.isNaN() && !d.isInfinite());
        } catch (NumberFormatException e) {
            return Optional.empty();
        }
    }

    /** The provider's error code: Auth0's errorCode, WorkOS's code or Clerk's errors[0].code. */
    private static String errorCode(byte[] text) {
        try {
            JsonNode body = MAPPER.readTree(text);
            if (body == null || !body.isObject()) {
                return null;
            }
            JsonNode code = body.has("errorCode") ? body.get("errorCode") : body.get("code");
            if (code == null && body.path("errors").isArray() && body.path("errors").size() > 0) {
                code = body.path("errors").get(0).get("code");
            }
            return code != null && code.isTextual() && !code.asText().isEmpty() ? code.asText() : null;
        } catch (IOException e) {
            return null;
        }
    }

    /**
     * One admin API call. A 404 is done (null); a 429 is waited out inside the action's budget; any
     * other failure throws ProviderActionException.
     */
    private static JsonNode send(JsonNode request, Map<String, String> paging, Context ctx, String item) {
        String method = request.get("method").asText();
        String path = request.get("path").asText()
                .replace("{user}", encode(ctx.user))
                .replace("{item}", encode(item == null ? "" : item));
        StringBuilder query = new StringBuilder();
        Map<String, String> params = new LinkedHashMap<>();
        if (request.has("query")) {
            request.get("query").fields().forEachRemaining(e -> params.put(e.getKey(), fill(e.getValue().asText(), ctx.user, item)));
        }
        if (paging != null) {
            params.putAll(paging);
        }
        for (Map.Entry<String, String> param : params.entrySet()) {
            query.append(query.length() == 0 ? "?" : "&").append(encode(param.getKey())).append('=').append(encode(param.getValue()));
        }
        byte[] body = null;
        if (request.has("body")) {
            try {
                body = MAPPER.writeValueAsBytes(fillJson(request.get("body"), ctx.user, item));
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        String label = ctx.name + " " + method + " " + request.get("path").asText();
        for (int retry = 0; ; retry++) {
            HttpRequest.Builder builder = HttpRequest.newBuilder(URI.create(ctx.base + path + query))
                    .timeout(Duration.ofSeconds(10))
                    .header("authorization", ctx.authorization)
                    .header("accept", "application/json")
                    .method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofByteArray(body));
            if (body != null) {
                builder.header("content-type", "application/json");
            }
            HttpResponse<InputStream> response;
            byte[] text;
            try {
                response = ctx.http.send(builder.build());
                try (InputStream stream = response.body()) {
                    text = stream == null ? new byte[0] : stream.readAllBytes();
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new ProviderActionException(ctx.name, 0, label + " was interrupted", null);
            } catch (Exception e) {
                throw new ProviderActionException(ctx.name, 0, label + " failed: " + e.getMessage(), null);
            }
            int status = response.statusCode();
            if (status == 429 && retry < LIMITS.get("retries").asInt()) {
                long wait = rateLimitWaitMs(response, retry);
                if (ctx.waitedMs + wait <= LIMITS.get("budget_ms").asLong()) {
                    ctx.waitedMs += wait;
                    try {
                        Thread.sleep(wait);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        throw new ProviderActionException(ctx.name, 0, label + " was interrupted", null);
                    }
                    continue;
                }
            }
            if (status == 404) {
                return null;
            }
            if (status < 200 || status >= 300) {
                throw new ProviderActionException(ctx.name, status, label + " answered " + status, errorCode(text));
            }
            if (text.length == 0) {
                return null;
            }
            try {
                return MAPPER.readTree(text);
            } catch (IOException e) {
                return null;
            }
        }
    }
}
